preset.frame_eqs_eel:
vb = vb*0.95 + (1-vb)*pow(bass,2)*0.02;
vvb = vvb*0.95 + (1-vvb)*vb*0.01;
vm = vm*0.95 + (1-vm)*pow(mid,2)*0.02;
vvm = vvm*0.95 + (1-vvm)*vm*0.01;
vt = vt*0.95 + (1-vt)*pow(treb,2)*0.02;
vvt = vvt*0.95 + (1-vvt)*vt*0.01;
vvb = min(1,max(0,vvb));
vvm = min(1,max(0,vvm));
vvt = min(1,max(0,vvt));

q1 = vvb*2;//0.5 + vb - vvb;
q2 = vvm*2;//0.5 + vm - vvm;
q3 = vvt*2;//0.5 + vt - vvt;

v=2;

bb = bb - vvb*v;
mm = mm - vvm*v;
tt = tt - vvt*v;

q4 = bb;
q5 = mm;
q6 = tt;

pi3 = 3.1415*2*0.3333;

t = (q4+q5+q6)*0.005;
c=3;
r = sin(t)*c;

g = sin(t+pi3)*c;

b = sin(t-pi3)*c;

ob_r = min(1,max(0,r));
ob_g = min(1,max(0,g));
ob_b = min(1,max(0,b));

preset.pixel_eqs_eel:
pi = asin(1);

x = x-0.5;
y = y- 0.5;

d = (q4-q6)*0.4 +  (rad-0.3)*(q1-q3)*2 + pi;
xx = sin(d)*x - cos(d)*y;
yy = cos(d)*x + sin(d)*y;


x = xx;
y = yy;


t = time*.2;
xh = x;
yh = y;

w = (q4-q6)*0.8;
m = -1 + q2*2;
wv = pi-sin(w)*m;
wh = pi-cos(w)*m;
d = 8*sqrt(q2);
ww = 1.2;
ddx = sin(2*pi - wv -(x)*ww);
ddy = sin(2*pi - wh -(y)*ww);
rx = if(above(ddx*ddy,0),sin(wv)/ddx,0);
ry = if(above(ddy*ddy,0),sin(wh)/ddy,0);

v = -(q2)*.1*(d/ww);

ax = ax + sin(w)*v;
ay = ay + cos(w)*v;

vx = if(equal(rx*ry,0),0,ax);
vy = if(equal(rx*ry,0),0,ay);

dx = (-xh*rx*ry*d + vx*.001);
dy = (-yh*rx*ry*d + vy*.001);

